import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#world');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9fc8c9);scene.fog=new THREE.Fog(0x9fc8c9,48,112);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xdff4ee,0x596c51,2.1));
const sun=new THREE.DirectionalLight(0xffedc4,2.4);sun.position.set(-25,40,18);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});
// Hand-shaped island terrain: a shallow sandy shelf that rises into a green interior.
const N=140,size=112,geo=new THREE.PlaneGeometry(size,size,N,N);geo.rotateX(-Math.PI/2);const pos=geo.attributes.position,colors=[];
const sand=new THREE.Color(0xcdbb8a),grass=new THREE.Color(0x557c56),high=new THREE.Color(0x365f4b),deep=new THREE.Color(0x203f37),c=new THREE.Color();
function terrainY(x,z){const r=Math.hypot(x,z),noise=Math.sin(x*.31+Math.sin(z*.19))*Math.cos(z*.27)*.62+Math.sin(x*.73+z*.55)*.17;const edge=1-clamp((r-35+noise)/10,0,1);return -1.05+edge*(.55+Math.max(0,1-r/42)*3.1+noise*.42)}
for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),r=Math.hypot(x,z);pos.setY(i,terrainY(x,z));const edge=clamp((r-32)/8,0,1),height=clamp((terrainY(x,z)+.9)/3.2,0,1);c.copy(sand).lerp(grass,1-edge);if(r<32)c.lerp(high,height*.68);if(r>43)c.copy(deep);colors.push(c.r,c.g,c.b)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const land=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));land.receiveShadow=true;scene.add(land);
// Ocean with gentle animated vertex waves.
const waterGeo=new THREE.PlaneGeometry(260,260,90,90);waterGeo.rotateX(-Math.PI/2);const waterMat=new THREE.MeshStandardMaterial({color:0x5ca7ac,roughness:.27,metalness:.06,transparent:true,opacity:.94});const water=new THREE.Mesh(waterGeo,waterMat);water.position.y=-1.05;scene.add(water);const waterBase=waterGeo.attributes.position.array.slice();
// Distant hazy island silhouette and sparse cloud puffs add a sense of horizon.
function puff(x,y,z,s){const g=new THREE.Group();for(let i=0;i<5;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(s*rand(.55,.9),10,8),new THREE.MeshBasicMaterial({color:0xf1eee1,transparent:true,opacity:.26}));m.position.set((i-2)*s*.53,rand(-.12,.18)*s,rand(-.18,.18)*s);g.add(m)}g.position.set(x,y,z);scene.add(g);return g}
const clouds=[puff(-35,23,-60,2.4),puff(35,29,-72,3),puff(62,21,-40,1.8)];
// Props are intentionally built from simple shapes so the world loads instantly.
const trunkMat=mat(0x846644),leafMat=mat(0x356b4b),leafLight=mat(0x6f9c5e),rockMat=mat(0x868c7b),berryMat=mat(0x9b514d),yellow=mat(0xe4c978);
function addPalm(x,z,s=1,decorative=false){const y=terrainY(x,z);const group=new THREE.Group();group.position.set(x,y,z);const h=rand(3.2,4.7)*s;const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13*s,.24*s,h,7),trunkMat);trunk.position.y=h/2;trunk.rotation.z=rand(-.09,.09);trunk.castShadow=true;group.add(trunk);for(let i=0;i<7;i++){const angle=i*Math.PI*2/7,frond=new THREE.Mesh(new THREE.ConeGeometry(.37*s,2.7*s,5),i%3===0?leafLight:leafMat);frond.position.set(Math.cos(angle)*.95*s,h+.12*s+Math.sin(i*2)*.12,Math.sin(angle)*.95*s);frond.rotation.z=-Math.cos(angle)*.9;frond.rotation.x=Math.sin(angle)*.9;frond.rotation.y=angle;frond.castShadow=true;group.add(frond)}scene.add(group);if(!decorative)interactables.push({type:'wood',x,z,group,used:false});return group}
function addRock(x,z){const group=new THREE.Group();group.position.set(x,terrainY(x,z),z);const count=2+Math.floor(Math.random()*3);for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.DodecahedronGeometry(rand(.4,.8),0),rockMat);m.position.set(rand(-.55,.55),rand(.18,.48),rand(-.45,.45));m.scale.set(rand(.8,1.4),rand(.55,.95),rand(.75,1.3));m.rotation.set(rand(0,1),rand(0,3),rand(0,1));m.castShadow=true;m.receiveShadow=true;group.add(m)}scene.add(group);interactables.push({type:'stone',x,z,group,used:false})}
function addBush(x,z){const group=new THREE.Group();group.position.set(x,terrainY(x,z),z);for(let i=0;i<5;i++){const b=new THREE.Mesh(new THREE.SphereGeometry(rand(.27,.42),10,8),mat(i%2?0x4d7847:0x638d50));b.position.set(rand(-.4,.4),rand(.2,.52),rand(-.35,.35));b.castShadow=true;group.add(b)}for(let i=0;i<7;i++){const berry=new THREE.Mesh(new THREE.SphereGeometry(.075,8,7),berryMat);berry.position.set(rand(-.45,.45),rand(.2,.65),rand(-.42,.42));group.add(berry)}scene.add(group);interactables.push({type:'berry',x,z,group,used:false})}
const interactables=[];
// Palms form loose clusters, with a clear playable clearing in the middle.
for(let i=0;i<30;i++){const a=rand(0,Math.PI*2),r=rand(14,32);addPalm(Math.cos(a)*r,Math.sin(a)*r,rand(.72,1.18),true)}
for(const [x,z] of [[-13,5],[16,-6],[5,18],[-18,-9],[23,11],[-8,-24],[30,-15],[0,30]])addPalm(x,z,rand(.82,1.05));
[[-17,-2],[-7,12],[13,7],[20,-17],[-23,-15],[7,-28],[29,5],[0,24]].forEach(([x,z])=>addRock(x,z));
[[-10,-10],[12,17],[-25,8],[25,-7],[2,-21]].forEach(([x,z])=>addBush(x,z));
// Small flowers and ground tufts, placed away from the core clearing.
for(let i=0;i<92;i++){const a=rand(0,Math.PI*2),r=rand(7,33),x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)<8)continue;const stem=new THREE.Mesh(new THREE.SphereGeometry(rand(.045,.09),5,4),i%4?leafLight:yellow);stem.position.set(x,terrainY(x,z)+.1,z);scene.add(stem)}

