// Small flowers and ground tufts, placed away from the core clearing.
for(let i=0;i<92;i++){const a=rand(0,Math.PI*2),r=rand(7,33),x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)<8)continue;const stem=new THREE.Mesh(new THREE.SphereGeometry(rand(.045,.09),5,4),i%4?leafLight:yellow);stem.position.set(x,terrainY(x,z)+.1,z);scene.add(stem)}
// A small, readable castaway silhouette.
const player=new THREE.Group();scene.add(player);const skin=mat(0xd2a77e),shirt=mat(0xc8784e),pants=mat(0x3b5450),dark=mat(0x443c2e);
const torso=new THREE.Mesh(new THREE.CylinderGeometry(.31,.38,.72,9),shirt);torso.position.y=1.04;torso.castShadow=true;player.add(torso);
const head=new THREE.Mesh(new THREE.SphereGeometry(.24,12,10),skin);head.position.y=1.59;head.castShadow=true;player.add(head);
const hair=new THREE.Mesh(new THREE.SphereGeometry(.245,10,7,0,Math.PI*2,0,Math.PI*.52),dark);hair.position.set(0,1.66,0);player.add(hair);
for(const side of [-1,1]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.12,.14,.56,7),pants);leg.position.set(side*.16,.37,0);leg.castShadow=true;player.add(leg);const arm=new THREE.Mesh(new THREE.CylinderGeometry(.085,.1,.54,7),skin);arm.position.set(side*.39,1.08,0);arm.rotation.z=side*-.16;player.add(arm)}
player.position.set(0,terrainY(0,0),0);
let campfire=null,fireLight=null,fireLit=false,fireBuilt=false;
const woodMat=mat(0x76513a),emberMat=new THREE.MeshBasicMaterial({color:0xff9a42});
function buildFire(){const g=new THREE.Group();g.position.set(player.position.x,terrainY(player.position.x,player.position.z)+.08,player.position.z);for(let i=0;i<4;i++){const log=new THREE.Mesh(new THREE.CylinderGeometry(.09,.11,1.45,7),woodMat);log.rotation.z=Math.PI/2;log.rotation.y=i*Math.PI/2;log.position.y=.12+i*.015;log.castShadow=true;g.add(log)}const stones=[];for(let i=0;i<8;i++){const a=i*Math.PI/4,s=new THREE.Mesh(new THREE.DodecahedronGeometry(.2,0),rockMat);s.position.set(Math.cos(a)*.67,.08,Math.sin(a)*.67);s.scale.set(1,.72,.92);g.add(s);stones.push(s)}const flame=new THREE.Mesh(new THREE.ConeGeometry(.28,.95,7),new THREE.MeshBasicMaterial({color:0xffae49,transparent:true,opacity:.93}));flame.position.y=.65;g.add(flame);const core=new THREE.Mesh(new THREE.ConeGeometry(.13,.62,6),new THREE.MeshBasicMaterial({color:0xffe399}));core.position.y=.49;g.add(core);scene.add(g);campfire=g;fireLight=new THREE.PointLight(0xff9b4e,0,13,2);fireLight.position.set(g.position.x,1.8+g.position.y,g.position.z);scene.add(fireLight);fireLit=true;fireBuilt=true;document.querySelector('#fireState').textContent='LIT';document.querySelector('#fireState').style.color='#f1c778';document.querySelector('#fireSlot').textContent='LIT';toast('A small flame against the coming dark.');updateQuest()}
let inventory={wood:0,stone:0,berries:2},health=100,hunger=88,thirst=82,gameStarted=false,gameEnded=false,worldTime=8.33,elapsed=0,day=1,selected=0;
const keys={};let yaw=0,camDistance=9,camHeight=5.1,nearest=null,toastTimer=0;
const prompt=document.querySelector('#prompt');const toastEl=document.querySelector('#toast');
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
function updateQuest(){document.querySelector('#woodCount').textContent=inventory.wood;document.querySelector('#stoneCount').textContent=inventory.stone;document.querySelector('#woodSlot').textContent=inventory.wood;document.querySelector('#stoneSlot').textContent=inventory.stone;document.querySelector('#berryCount').textContent=inventory.berries;document.querySelector('#qWood').classList.toggle('done',inventory.wood>=6);document.querySelector('#qStone').classList.toggle('done',inventory.stone>=4);document.querySelector('#qFire').classList.toggle('done',fireLit);}
function updateNeeds(){for(const [id,value] of [['health',health],['hunger',hunger],['thirst',thirst]]){document.querySelector('#'+id+'Bar').style.width=clamp(value,0,100)+'%';document.querySelector('#'+id+'Num').textContent=Math.ceil(clamp(value,0,100))}const condition=document.querySelector('#conditionText');condition.textContent=(hunger<25||thirst<25)?'WEAK':health<45?'HURT':'STEADY';condition.style.color=condition.textContent==='STEADY'?'#a8d1ad':'#e4ad85'}
function setPrompt(text){prompt.textContent=text;prompt.style.display=text?'block':'none'}
function interact(){if(!gameStarted)return;if(nearest){const o=nearest;if(o.type==='wood'){inventory.wood+=1;toast('Gathered driftwood  +1');o.used=true;o.group.visible=false}else if(o.type==='stone'){inventory.stone+=1;toast('Collected smooth stone  +1');o.used=true;o.group.visible=false}else if(o.type==='berry'){inventory.berries+=2;toast('Wild berries  +2');o.used=true;o.group.visible=false}updateQuest();return}if(Math.hypot(player.position.x,player.position.z)>34){thirst=Math.max(0,thirst-1);toast('The salt water is no good to drink.');return}if(Math.hypot(player.position.x,player.position.z)>29){toast('The tide is cool, but the water is salty.');return}toast('No supplies within reach. Follow the shoreline.');}
function eat(){if(inventory.berries<=0){toast('No berries left. Gather from a berry bush.');return}if(hunger>94){toast('You are not hungry yet.');return}inventory.berries--;hunger=clamp(hunger+27,0,100);updateQuest();toast('Sweet and tart. Hunger eased.')}
function placeFire(){if(!gameStarted)return;if(fireBuilt){toast('Your fire is already burning.');return}if(inventory.wood<6||inventory.stone<4){toast(`Need ${Math.max(0,6-inventory.wood)} wood and ${Math.max(0,4-inventory.stone)} stone to build.`);return}inventory.wood-=6;inventory.stone-=4;buildFire();updateQuest()}
function updateTarget(){nearest=null;let dBest=3.25;for(const o of interactables){if(o.used)continue;const d=Math.hypot(o.x-player.position.x,o.z-player.position.z);if(d<dBest){dBest=d;nearest=o}}if(nearest){const label=nearest.type==='wood'?'Gather driftwood':nearest.type==='stone'?'Collect smooth stone':'Pick wild berries';setPrompt('E  ·  '+label)}else setPrompt('')}
function endGame(won){gameEnded=true;const m=document.querySelector('#endMessage');document.querySelector('#endSymbol').textContent=won?'✧':'☾';document.querySelector('#endTitle').textContent=won?'A light in the dark':'The tide turns';document.querySelector('#endCopy').textContent=won?'You kept the flame through the first night. The island is beginning to feel like home. Keep exploring, and see what the next day brings.':'The island asks for more than you had to give. The tide keeps its own time. Start again, and make shelter before dusk.';document.querySelector('#continueBtn').textContent=won?'Continue exploring':'Try again';m.classList.add('open')}

